#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Group {
    /// No authentication (`/api/health`).
    Public,
    /// Main `/api/v1` group.
    Main,
    /// `/api/v1/disable` group.
    Disable,
}

#[derive(Debug)]
pub struct RouteSpec {
    pub method: &'static str,
    /// Upstream URI (`routes/api.php` with prefixes), also the axum path.
    pub uri: &'static str,
    pub group: Group,
    /// Each inner slice is one `api.ability:` middleware (any-of); all must pass.
    pub abilities: &'static [&'static [Ability]],
}

use Ability::{Deploy, Read, Write};

const R: &[&[Ability]] = &[&[Read]];
const W: &[&[Ability]] = &[&[Write]];
const NONE: &[&[Ability]] = &[];
/// `api.ability:deploy`.
const D: &[&[Ability]] = &[&[Deploy]];
/// `api.ability:write` then `api.ability:deploy`.
const WD: &[&[Ability]] = &[&[Write], &[Deploy]];

